import { useEffect, useMemo, useState, type ChangeEvent, type ReactNode } from "react";
import {
  HiArrowDownTray, HiArrowLeftOnRectangle, HiArrowPath, HiArrowTopRightOnSquare, HiBars3BottomLeft,
  HiCheck, HiChevronDown, HiChevronUp, HiDocumentDuplicate, HiEye, HiFolderOpen,
  HiHome, HiInboxStack, HiLockClosed, HiMiniPlus, HiOutlineArrowsUpDown,
  HiOutlineBuildingOffice2, HiOutlineChartBar, HiOutlineCog6Tooth, HiOutlineDocumentText,
  HiOutlinePhoto, HiOutlineTrash, HiOutlineUsers, HiPencilSquare, HiXMark,
} from "react-icons/hi2";
import { DEFAULT_PAGE_BUILDER, type BlockType, type BuilderBlock, type BuilderPage, type PageBuilderData } from "../page-builder/types";
import type { AdminSessionUser } from "./AdminGate";

type Section = "dashboard" | "builder" | "pages" | "media" | "enquiries" | "access" | "settings";
type ToastTone = "success" | "error" | "info";
type Toast = { tone: ToastTone; text: string } | null;
type LooseObject = Record<string, unknown>;
type AccessPayload = { roles: LooseObject[]; permissions: LooseObject[]; users: LooseObject[]; enforcement?: string };

const iconClass = "h-4 w-4";
const genericBlocks: { type: BlockType; title: string; note: string }[] = [
  { type: "hero", title: "Hero", note: "Headline, calls to action and image" },
  { type: "text", title: "Text", note: "Flexible content section" },
  { type: "image", title: "Image", note: "Full-width visual and caption" },
  { type: "services", title: "Services", note: "Service cards" },
  { type: "features", title: "Features", note: "Dark feature grid" },
  { type: "cta", title: "Call to action", note: "Conversion banner" },
  { type: "gallery", title: "Gallery", note: "Image grid" },
  { type: "testimonials", title: "Testimonials", note: "Client feedback cards" },
  { type: "contact", title: "Contact", note: "Contact conversion section" },
  { type: "faq", title: "FAQ", note: "Expandable questions" },
];
const builtInLabels: Record<string, string> = {
  siteHero: "Homepage Hero", siteAbout: "About Section", siteDivisions: "Division Overview", siteSolutions: "Solutions Division", siteInterior: "Interior Division", siteTrading: "Trading Division", siteIndustries: "Industries", siteGlobalReach: "Global Reach", siteTestimonials: "Testimonials", siteContact: "Contact",
};

const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const makeId = (prefix = "block") => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
const fieldText = (obj: LooseObject, key: string, fallback = "") => typeof obj[key] === "string" ? obj[key] as string : fallback;
const fieldItems = (obj: LooseObject, key: string): LooseObject[] => Array.isArray(obj[key]) ? obj[key].filter((value): value is LooseObject => Boolean(value) && typeof value === "object" && !Array.isArray(value)) : [];

function slugify(value: string) {
  return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "").slice(0, 70);
}

